package backend

import("math";"path/filepath";"strings";"testing")
func canvasFixture()CanvasDocument{return CanvasDocument{Version:1,ActiveWorkspaceID:"ws-1",Workspaces:[]CanvasWorkspace{{ID:"ws-1",Name:"镜头",Viewport:CanvasDocumentViewport{Scale:1},Nodes:[]CanvasDocumentNode{{ID:"node-1",Type:"video",X:-500,Width:480,Height:270,Src:"/media/full/abc"}},SelectedNodeID:"node-1"}},AppliedVideoTaskIDs:[]string{"task-1"}}}
func TestCanvasDocumentRoundtripAndConflict(t *testing.T){path:=filepath.Join(t.TempDir(),"canvas.json");doc,err:=saveCanvasDocument(path,canvasFixture(),0);if err!=nil{t.Fatal(err)};loaded,err:=readCanvasDocument(path);if err!=nil||loaded.Revision!=1||loaded.Workspaces[0].Nodes[0].X!=-500{t.Fatal(loaded,err)};if _,err=saveCanvasDocument(path,doc,0);err==nil||!strings.Contains(err.Error(),"CANVAS_CONFLICT"){t.Fatal(err)};loaded,_=readCanvasDocument(path);if loaded.Revision!=1{t.Fatal("conflict overwrote file")}}
func TestCanvasRejectsUnsafeOrInvalidNodes(t *testing.T){for _,src:=range []string{"javascript:alert(1)","data:video/mp4;base64,AAAA","https://secret@host.test/a","https://host.test/a?key=secret","/media/../secret"}{doc:=canvasFixture();doc.Workspaces[0].Nodes[0].Src=src;if validateCanvasDocument(doc)==nil{t.Fatal(src)}};doc:=canvasFixture();doc.Workspaces[0].Nodes[0].X=math.NaN();if validateCanvasDocument(doc)==nil{t.Fatal("NaN accepted")};doc=canvasFixture();doc.Workspaces[0].SelectedNodeID="missing";if validateCanvasDocument(doc)==nil{t.Fatal("dangling selection")}}
